            .safeModeTitle: "безпечний режим",
            .convAudioOnlyHint: "єдиний формат на вихід — у macOS немає вбудованого кодувальника MP3/FLAC",
            .convFileFailed: "не вдалося: система не змогла прочитати цей файл",
            .convCompressLabel: "стиснення",
